spawnFunction.source:
// Gives each firefly its own blink: custom.x = phase, custom.y = blinks per second, custom.z = wander seed.
[[visible]] void fireflySpawn(thread ParticleState &particle, float deltaTime, float time, constant float4 *parameters) {
    uint h = particle.id * 747796405u + 2891336453u;
    h = ((h >> ((h >> 28u) + 4u)) ^ h) * 277803737u;
    float a = float(h & 0xffffu) / 65535.0;
    float b = float(h >> 16u) / 65535.0;
    particle.custom = float4(a * 6.2831853, mix(parameters[0].x, parameters[0].y, b), a * 100.0 + b, 0);
}

updateFunction.source:
// Blinks with the phase and rate stored at spawn: size and color pulse, and each firefly wanders on its own path.
// parameters[0] = (slowest blinks per second, fastest, glow size, wander speed).
[[visible]] void fireflyUpdate(thread ParticleState &particle, float deltaTime, float time, constant float4 *parameters) {
    float4 settings = parameters[0];
    float pulse = pow(0.5 + 0.5 * sin(particle.custom.x + time * particle.custom.y * 6.2831853), 6.0);
    particle.size = mix(0.15, settings.z, pulse);
    particle.color = float4(mix(float3(0.15, 0.35, 0.0), float3(0.75, 1.0, 0.15), pulse), mix(0.25, 1.0, pulse));
    float seed = particle.custom.z;
    float3 wander = float3(sin(time * 0.7 + seed), sin(time * 0.9 + seed * 1.7) * 0.5, cos(time * 0.6 + seed * 2.3));
    particle.velocity = mix(particle.velocity, wander * settings.w, saturate(deltaTime * 2.0));
}
